/// <summary>
/// Constructs a new instance of <c>VendLegalEntityIDLookupEventHandler</c> class.
/// </summary>
/// <returns>
/// A <c>VendLegalEntityIDLookupEventHandler</c> class.
/// </returns>
public static VendLegalEntityIDLookupEventHandler construct()
{
    return new VendLegalEntityIDLookupEventHandler();
}

/// <Summary>
/// Builds and displays a table lookup for the METVendLegalEntity table showing VendLegalEntityID, VendParentCompanyID, and VendParentCompany.
/// </Summary>
/// <Param name="_callingControl">The FormStringControl that initiated the lookup.</Param>
public void VendLegalEntityID_OnLookup(FormStringControl _callingControl)
{
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(METVendLegalEntity), _callingControl);

    sysTableLookup.addLookupfield(fieldNum(METVendLegalEntity, VendLegalEntityID));
    sysTableLookup.addLookupfield(fieldNum(METVendLegalEntity, VendParentCompanyID));
    sysTableLookup.addLookupfield(fieldNum(METVendLegalEntity, VendParentCompany));

    sysTableLookup.performFormLookup();
}
